def islands(g):
    if not g: return 0
    R, C = len(g), len(g[0])
    def dfs(r, c):
        if r < 0 or c < 0 or r >= R or c >= C or g[r][c] != '1': return
        g[r][c] = '0'
        dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1)
    n = 0
    for r in range(R):
        for c in range(C):
            if g[r][c] == '1':
                dfs(r, c); n += 1
    return n
